/**
 * Python-style exception objects plus CPython/PyInstaller traceback rendering.
 *
 * The reference program is a PyInstaller one-file bundle, so an unhandled
 * exception writes a normal CPython traceback to stderr and then PyInstaller's
 * own `[PYI-<pid>:ERROR] ...` line. Both are reproduced byte-for-byte here.
 */

import process from 'node:process';

/** Number of spaces CPython puts in front of a source line inside a traceback. */
const SOURCE_INDENT = 4;

/**
 * Frame 1 of every traceback this program can produce: the single statement of
 * test2.py that constructs the PBKDF2 object. CPython underlines the
 * sub-expression that actually raised, which here is always the
 * `pbkdf2.PBKDF2(...)` call (the trailing `.read(20)` is never reached).
 */
const MAIN_SOURCE =
  'result = pbkdf2.PBKDF2(args.a, args.b, iterations=args.c).read(20)  # 派生 20 字节密钥';
const MAIN_CARET_EXPR = 'pbkdf2.PBKDF2(args.a, args.b, iterations=args.c)';

/** `pbkdf2.py` line reported for `_setup` when the error carries no `frameLine`. */
const DEFAULT_SETUP_LINE = 205;

/** Base class for every exception we mirror from Python. */
export class PyError extends Error {
  /**
   * @param {string} type Python exception class name, e.g. `'ValueError'`.
   * @param {string} message Python's `str(exc)` text.
   */
  constructor(type, message) {
    super(message);
    this.name = type;
    this.pyType = type;
    this.pyMessage = message;
    /**
     * Line inside `pbkdf2.py`'s `_setup` that raised. The raising module tags
     * this (193 passphrase, 197 salt, 205 iterations) so the traceback's last
     * frame matches the real interpreter.
     * @type {number|undefined}
     */
    this.frameLine = undefined;
  }
}

/** Python `ValueError`. */
export class PyValueError extends PyError {
  /** @param {string} message */
  constructor(message) {
    super('ValueError', message);
  }
}

/**
 * Python `UnicodeEncodeError` as raised by `str.encode('UTF-8')` when the
 * string holds a lone surrogate produced by argv's surrogateescape decoding.
 */
export class PyUnicodeEncodeError extends PyError {
  /**
   * @param {number} codePoint The offending code point (a lone surrogate).
   * @param {number} position Index of that code point, counted in Python code
   *   points (astral characters count as one).
   */
  constructor(codePoint, position) {
    super(
      'UnicodeEncodeError',
      `'utf-8' codec can't encode character '${escapeCodePoint(codePoint)}' ` +
        `in position ${position}: surrogates not allowed`,
    );
    this.codePoint = codePoint;
    this.position = position;
  }
}

/**
 * Render one code point the way Python escapes it inside `repr()` and inside
 * codec error messages: `\xNN`, `\uNNNN` or `\UNNNNNNNN`, always lowercase hex.
 * @param {number} cp
 * @returns {string}
 */
export function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Byte offsets differ from Python's character offsets, so locate `needle` and
 * report where it starts measured in code points rather than UTF-16 units.
 * @param {string} haystack
 * @param {string} needle
 * @returns {number} Code-point index, or -1 when absent.
 */
function codePointIndexOf(haystack, needle) {
  const at = haystack.indexOf(needle);
  if (at < 0) return -1;
  return Array.from(haystack.slice(0, at)).length;
}

/**
 * Work out which columns of a frame's source line get underlined with `^`.
 * `caret` may be an explicit `{start, length}` span or `true`, in which case
 * the frame's `caretExpr` sub-expression is located inside the source (falling
 * back to underlining the whole line).
 * @param {{source?: string, caret?: boolean|{start: number, length: number}, caretExpr?: string}} frame
 * @returns {{start: number, length: number}|null}
 */
function caretSpan(frame) {
  const { caret, source } = frame;
  if (!caret || typeof source !== 'string') return null;
  if (typeof caret === 'object') {
    return { start: caret.start, length: caret.length };
  }
  if (typeof frame.caretExpr === 'string') {
    const start = codePointIndexOf(source, frame.caretExpr);
    if (start >= 0) return { start, length: Array.from(frame.caretExpr).length };
  }
  return { start: 0, length: Array.from(source).length };
}

/**
 * The final `Type: message` line. Python omits the colon when `str(exc)` is
 * empty.
 * @param {unknown} err
 * @returns {string}
 */
function exceptionLine(err) {
  const type = (err && (err.pyType || err.name)) || 'Exception';
  const message = err && err.pyMessage !== undefined ? err.pyMessage : err && err.message;
  return message ? `${type}: ${message}` : `${type}`;
}

/**
 * Format a CPython traceback from innermost-last frames.
 * @param {Array<{file: string, line: number, name: string, source?: string,
 *   caret?: boolean|{start: number, length: number}, caretExpr?: string}>} frames
 * @param {unknown} err
 * @returns {string} Newline-terminated traceback text.
 */
export function formatTraceback(frames, err) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    // Frames from the bundled pbkdf2.py have no source available, so
    // PyInstaller prints only the location line for them.
    if (typeof frame.source !== 'string' || frame.source.length === 0) continue;
    lines.push(' '.repeat(SOURCE_INDENT) + frame.source);
    const span = caretSpan(frame);
    if (span && span.length > 0) {
      lines.push(' '.repeat(SOURCE_INDENT + span.start) + '^'.repeat(span.length));
    }
  }
  lines.push(exceptionLine(err));
  return lines.join('\n') + '\n';
}

/**
 * Produce the complete stderr text for a fatal error: the traceback plus
 * PyInstaller's trailing failure line.
 * @param {unknown} err
 * @returns {string} Newline-terminated stderr text.
 */
export function renderFatal(err) {
  const setupLine =
    err && Number.isInteger(err.frameLine) ? err.frameLine : DEFAULT_SETUP_LINE;
  const frames = [
    {
      file: 'test2.py',
      line: 12,
      name: '<module>',
      source: MAIN_SOURCE,
      caret: true,
      caretExpr: MAIN_CARET_EXPR,
    },
    { file: 'pbkdf2.py', line: 141, name: '__init__' },
    { file: 'pbkdf2.py', line: setupLine, name: '_setup' },
  ];
  return (
    formatTraceback(frames, err) +
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test2' due to unhandled exception!\n`
  );
}

/**
 * Python `int(str)` and `repr(str)` semantics, reproduced closely enough that
 * argparse's `type=int` accepts and rejects exactly what CPython does.
 */

import { PyValueError, escapeCodePoint } from './pyerror.mjs';

// Re-exported so callers can reach Python's ValueError through this module too.
export { PyValueError };

/** Widest contiguous run of Nd code points in Unicode is 50; scan generously. */
const RUN_SCAN_LIMIT = 100;

const ND_RE = /\p{Nd}/u;
// Python's str.isprintable(): false for these categories, with U+0020 as the
// one explicit exception (it is Zs but still prints as itself).
const NON_PRINTABLE_RE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/** Raised when a string is not a valid Python base-10 integer literal. */
export class PyIntParseError extends Error {
  /** @param {string} text The rejected input. */
  constructor(text) {
    super(`invalid literal for int() with base 10: ${pyRepr(text)}`);
    this.name = 'PyIntParseError';
    this.text = text;
  }
}

/**
 * ASCII whitespace as recognised by CPython's `Py_ISSPACE`, which is what the
 * integer parser itself uses. Note this deliberately excludes U+001C-U+001F:
 * `str.strip()` treats those as whitespace but `int()` does not.
 * @param {string} ch
 */
function isAsciiSpace(ch) {
  return ch === ' ' || (ch >= '\t' && ch <= '\r');
}

/**
 * Non-ASCII whitespace as recognised by CPython's `Py_UNICODE_ISSPACE`.
 * @param {number} cp
 */
function isUnicodeSpace(cp) {
  return (
    cp === 0x85 ||
    cp === 0xa0 ||
    cp === 0x1680 ||
    (cp >= 0x2000 && cp <= 0x200a) ||
    cp === 0x2028 ||
    cp === 0x2029 ||
    cp === 0x202f ||
    cp === 0x205f ||
    cp === 0x3000
  );
}

/** @param {number} cp */
function isNd(cp) {
  return cp >= 0 && cp <= 0x10ffff && ND_RE.test(String.fromCodePoint(cp));
}

/**
 * Numeric value of a Unicode decimal digit, i.e. CPython's
 * `Py_UNICODE_TODECIMAL`.
 *
 * Nd code points always come in complete, contiguous 0-9 blocks, but several
 * blocks can sit back to back (the mathematical digits occupy one unbroken
 * 50-code-point run at U+1D7CE-U+1D7FF). Simply walking back to the first
 * non-Nd neighbour would therefore mis-value every block but the first, so
 * find the whole run and take the offset modulo 10.
 *
 * @param {number} cp
 * @returns {number} 0-9, or -1 when `cp` is not a decimal digit.
 */
function decimalValue(cp) {
  if (!isNd(cp)) return -1;
  let lo = cp;
  while (lo > 0 && cp - lo < RUN_SCAN_LIMIT && isNd(lo - 1)) lo--;
  let hi = cp;
  while (hi < 0x10ffff && hi - cp < RUN_SCAN_LIMIT && isNd(hi + 1)) hi++;
  const runLength = hi - lo + 1;
  // A run that is not a whole number of blocks cannot happen in Unicode;
  // fall back to treating the run start as zero if one ever appears.
  if (runLength % 10 !== 0) return Math.min(cp - lo, 9);
  return (cp - lo) % 10;
}

/**
 * CPython's `_PyUnicode_TransformDecimalAndSpaceToASCII`: code points below 127
 * pass through untouched, Unicode whitespace collapses to a plain space, and
 * Unicode decimal digits become their ASCII equivalents. Anything else becomes
 * `'?'`, which the ASCII parser then rejects.
 * @param {string} text
 * @returns {string}
 */
function transformDecimalAndSpace(text) {
  let out = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 127) {
      out += ch;
    } else if (isUnicodeSpace(cp)) {
      out += ' ';
    } else {
      const digit = decimalValue(cp);
      out += digit >= 0 ? String(digit) : '?';
    }
  }
  return out;
}

/**
 * CPython's `PyLong_FromString` for base 10, over an already-ASCII string.
 * @param {string} text
 * @returns {number|null} The value, or null when the literal is malformed.
 */
function parseAsciiInt(text) {
  const end = text.length;
  let i = 0;
  while (i < end && isAsciiSpace(text[i])) i++;

  let negative = false;
  if (i < end && (text[i] === '+' || text[i] === '-')) {
    negative = text[i] === '-';
    i++;
  }

  // An underscore is only legal strictly between two digits, so track whether
  // a digit is currently mandatory. It starts mandatory (rejecting `_10` and
  // `+_1`) and becomes mandatory again after every underscore (rejecting `1__0`
  // and, once the loop ends, `10_`).
  let digits = '';
  let digitRequired = true;
  while (i < end) {
    const ch = text[i];
    if (ch >= '0' && ch <= '9') {
      digits += ch;
      digitRequired = false;
      i++;
    } else if (ch === '_' && !digitRequired) {
      digitRequired = true;
      i++;
    } else {
      break;
    }
  }
  if (digits.length === 0 || digitRequired) return null;

  while (i < end && isAsciiSpace(text[i])) i++;
  if (i !== end) return null;

  // Python integers are arbitrary precision; accumulate exactly and only then
  // narrow to a Number (which may saturate to Infinity for absurd inputs).
  const magnitude = BigInt(digits);
  return Number(negative ? -magnitude : magnitude);
}

/**
 * Python's `int(str)`.
 * @param {string} text
 * @returns {number}
 * @throws {PyIntParseError} When `text` is not a valid base-10 integer.
 */
export function pyInt(text) {
  const value = parseAsciiInt(transformDecimalAndSpace(text));
  if (value === null) throw new PyIntParseError(text);
  return value;
}

/** @param {number} cp */
function isPrintable(cp) {
  if (cp === 0x20) return true;
  return !NON_PRINTABLE_RE.test(String.fromCodePoint(cp));
}

/**
 * Python's `repr()` of a str, as embedded in argparse's
 * `invalid int value: 'x'` message.
 *
 * Single quotes are preferred; double quotes are used only when the string
 * contains a single quote but no double quote. Backslash, newline, carriage
 * return and tab get named escapes, everything non-printable gets a numeric
 * escape (including lone surrogates, which render as `\udcXX`).
 *
 * @param {string} text
 * @returns {string}
 */
export function pyRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
      continue;
    }
    if (ch === '\n') {
      out += '\\n';
      continue;
    }
    if (ch === '\r') {
      out += '\\r';
      continue;
    }
    if (ch === '\t') {
      out += '\\t';
      continue;
    }
    const cp = ch.codePointAt(0);
    out += isPrintable(cp) ? ch : escapeCodePoint(cp);
  }
  return out + quote;
}

