import { spawnSync } from 'node:child_process';
import { pyInt, pyRepr, PyIntParseError } from '/output/lib/pyint.mjs';

const EXE = '/workspace/dataset/test2_executable';
const run = (c) => {
  const r = spawnSync(EXE, ['--a', 'p', '--b', 's', '--c', c], { encoding: 'utf8' });
  const err = (r.stderr || '').trim().split('\n').pop() || '';
  if (r.status === 0) return { kind: 'ok', hash: r.stdout.trim() };
  const m = err.match(/invalid int value: (.*)$/);
  if (m) return { kind: 'reject', repr: m[1] };
  if (/ValueError: iterations must be at least 1/.test((r.stderr || '').trim()))
    return { kind: 'lt1' };
  return { kind: 'other', err };
};

// Cache reference hashes for small positive iteration counts.
const hashCache = new Map();
const hashFor = (n) => {
  if (!hashCache.has(n)) hashCache.set(n, run(String(n)).hash);
  return hashCache.get(n);
