push(' 10 ', '\t10\n', '\v10\f', '\r10', '10_', '_10', '1__0', '+_1', '- 1', '1 0', '+ 10');
push('½', '²', 'Ⅻ', '⑤', '﹢10', '⁵', '₅', '〇', '一');
