  ' ', ' ', ' ', '　', '', '', '​', '᠎', ''])
  push(ws + '10', '10' + ws, ws + '10' + ws);
// digit scripts: one char per Nd block start we can reach, valued 0..9
const ndStarts = [0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66, 0x0be6,
  0x0c66, 0x0ce6, 0x0d66, 0x0e50, 0x0ed0, 0x0f20, 0x1040, 0x17e0, 0x1810, 0x1946, 0x19d0,
  0xa620, 0xff10, 0x104a0, 0x1d7ce, 0x1d7d8, 0x1d7e2, 0x1d7ec, 0x1d7f6, 0x1e950];
for (const s of ndStarts) {
  push(String.fromCodePoint(s + 1) + String.fromCodePoint(s));      // "10"
  push(String.fromCodePoint(s + 5));                                 // "5"
  push(String.fromCodePoint(s));                                     // "0"
  push(String.fromCodePoint(s + 9) + String.fromCodePoint(s + 3));   // "93"
}
// repr-stressing rejects
