  '‍', '؀', 'ꀀ', '᠎', 'ᐧ', '⁠'])
  push(s);
// random junk
const pool = '0123456789_+-. \tabxX٠۰\u{1d7d9} ';
for (let i = 0; i < 220; i++) {
  let s = '';
  const n = 1 + Math.floor(Math.random() * 6);
  for (let j = 0; j < n; j++) s += [...pool][Math.floor(Math.random() * [...pool].length)];
  push(s);
