const nd = [];
for (let cp = 0; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (ND.test(String.fromCodePoint(cp))) nd.push(cp);
}
const runs = [];
for (const cp of nd) {
  const last = runs[runs.length - 1];
  if (last && cp === last.hi + 1) last.hi = cp;
  else runs.push({ lo: cp, hi: cp });
}
const badRuns = runs.filter((r) => (r.hi - r.lo + 1) % 10 !== 0);
console.log(`Nd code points: ${nd.length}, runs: ${runs.length}, runs not a multiple of 10: ${badRuns.length}`);
if (badRuns.length) console.log(badRuns.map((r) => r.lo.toString(16)).join(','));

const blocks = [];
for (const r of runs) for (let s = r.lo; s < r.hi; s += 10) blocks.push(s);
console.log(`blocks (expected 0-9 sets): ${blocks.length}`);

// 2. Self-check: pyInt of a two-digit string from each block must equal 42.
let selfFail = 0;
for (const s of blocks) {
  const got = pyInt(String.fromCodePoint(s + 4) + String.fromCodePoint(s + 2));
  if (got !== 42) { selfFail++; console.log('BLOCK FAIL U+' + s.toString(16), got); }
}
console.log(`block self-check: ${selfFail === 0 ? 'ALL PASS' : selfFail + ' FAILURES'}`);

