const EXE = '/workspace/dataset/test2_executable';
const run = (c) => spawnSync(EXE, ['--a', 'p', '--b', 's', '--c', c], { encoding: 'utf8' });
const ref7 = run('7').stdout.trim();
let diffFail = 0, diffN = 0;
const sample = blocks.filter((_, i) => i % 3 === 0);
for (const s of sample) {
  const r = run(String.fromCodePoint(s + 7));
  diffN++;
  if (r.status !== 0 || r.stdout.trim() !== ref7) {
    diffFail++;
    console.log('DIFF FAIL U+' + s.toString(16), r.status, (r.stderr || '').trim().split('\n').pop());
  }
