// 4. repr differential over random code points (each is a reject, so the
//    executable echoes Python's repr back to us).
let reprFail = 0, reprN = 0;
const seen = new Set();
const picks = [];
while (picks.length < 300) {
  const cp = Math.floor(Math.random() * 0x110000);
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (ND.test(String.fromCodePoint(cp))) continue; // would parse as a digit
  if (seen.has(cp)) continue;
  seen.add(cp);
  picks.push(cp);
}
for (const cp of picks) {
  const s = 'z' + String.fromCodePoint(cp); // 'z' keeps it an invalid int
  const r = run(s);
  const line = (r.stderr || '').trim().split('\n').pop() || '';
  const m = line.match(/invalid int value: (.*)$/);
  if (!m) continue; // whitespace-only oddities that argparse handled elsewhere
  reprN++;
  const mine = pyRepr(s);
  if (mine !== m[1]) {
    reprFail++;
    console.log('REPR FAIL U+' + cp.toString(16), 'mine', mine, 'ref', m[1]);
  }
}
console.log(`repr differential (${reprN} code points): ${reprFail === 0 ? 'ALL PASS' : reprFail + ' FAILURES'}`);

