import { spawnSync } from 'node:child_process';
import { pyRepr } from '/output/lib/pyint.mjs';

const EXE = '/workspace/dataset/test2_executable';
const ND = /\p{Nd}/u;
const refRepr = (s) => {
  const r = spawnSync(EXE, ['--a', 'p', '--b', 's', '--c', s], { encoding: 'utf8' });
  const m = ((r.stderr || '').trim().split('\n').pop() || '').match(/invalid int value: (.*)$/);
  return m ? m[1] : null;
};

let n = 0, fail = 0;
const check = (cp) => {
  const s = 'z' + String.fromCodePoint(cp);
  const ref = refRepr(s);
  if (ref === null) return;
  n++;
  if (pyRepr(s) !== ref) {
    fail++;
    if (fail <= 15) console.log('FAIL U+' + cp.toString(16), 'mine', pyRepr(s), 'ref', ref);
  }
};

// Exhaustive around the Unicode 15.0/15.1 boundary blocks.
console.log('-- Ext I boundary sweep --');
for (const cp of [0x2ebee, 0x2ebef, 0x2ebf0, 0x2ebf1, 0x2ec00, 0x2ed00, 0x2ee5c, 0x2ee5d,
  0x2ee5e, 0x2ee5f, 0x2ef00, 0x2f7ff, 0x2f800, 0x2fa1d, 0x2fa1e,
  0x30000, 0x3134a, 0x3134b, 0x31350, 0x323af, 0x323b0, 0x3fffd, 0x40000, 0x10fffd, 0x10ffff])
  check(cp);
// Sampled sweep inside Ext I.
for (let cp = 0x2ebf0; cp <= 0x2ee5d; cp += 37) check(cp);

// Wide random sweep over all planes.
console.log('-- random sweep --');
const seen = new Set();
let picks = 0;
while (picks < 600) {
  const cp = Math.floor(Math.random() * 0x110000);
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (ND.test(String.fromCodePoint(cp))) continue;
  if (seen.has(cp)) continue;
  seen.add(cp);
  picks++;
  check(cp);
}
console.log(`repr differential: ${n} code points -> ${fail === 0 ? 'ALL PASS' : fail + ' FAILURES'}`);

import { spawnSync } from 'node:child_process';
import { pyRepr, pyInt, PyIntParseError } from '/output/lib/pyint.mjs';

const EXE = '/workspace/dataset/test2_executable';
const alphabet = [...'\'"\\\n\r\t\v\f\x00\x1b abzX09_+-.', '­', '​', '́',
  '\u{1f600}', '\udcff', ' ', ' ', '\u{1d7d9}', '٠', '�', '\u{e0001}'];

let n = 0, fail = 0;
for (let i = 0; i < 700; i++) {
  const len = 1 + Math.floor(Math.random() * 7);
  let s = '';
  for (let j = 0; j < len; j++) s += alphabet[Math.floor(Math.random() * alphabet.length)];
  if (s.includes('\x00')) continue; // execve cannot carry NUL in argv
  const r = spawnSync(EXE, ['--a', 'p', '--b', 's', '--c', s], { encoding: 'utf8' });
  const tail = (r.stderr || '').trim().split('\n').pop() || '';
  const m = tail.match(/invalid int value: (.*)$/);
  if (!m) {
    // Accepted (or <1): confirm we also accept and agree on the value.
    let mine = null;
    try { mine = pyInt(s); } catch (e) { if (e instanceof PyIntParseError) mine = 'REJECT'; }
    if (mine === 'REJECT') { fail++; console.log('FAIL wrongly-rejected', JSON.stringify(s), tail || r.stdout.trim()); }
    continue;
  }
  n++;
  const mine = pyRepr(s);
  if (mine !== m[1]) {
    fail++;
    if (fail <= 15) console.log('FAIL', JSON.stringify(s), '\n  mine', mine, '\n  ref ', m[1]);
  }
}
console.log(`multi-char repr fuzz: ${n} strings -> ${fail === 0 ? 'ALL PASS' : fail + ' FAILURES'}`);

import { spawnSync } from 'node:child_process';
import { pyRepr } from '/output/lib/pyint.mjs';

const EXE = '/workspace/dataset/test2_executable';

/**
 * Node's spawnSync turns lone surrogates in argv into U+FFFD, so hand the raw
 * bytes to the process through sh + printf instead. Lone surrogate U+DCxx maps
 * back to the raw byte 0xxx, which Python re-decodes with surrogateescape.
 */
function refRepr(s) {
  const bytes = [];
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp >= 0xdc80 && cp <= 0xdcff) bytes.push(cp - 0xdc00);
    else for (const b of Buffer.from(ch, 'utf8')) bytes.push(b);
  }
  const esc = bytes.map((b) => '\\' + b.toString(8).padStart(3, '0')).join('');
  // `--c=` form so values starting with '-' are not mistaken for options.
  const r = spawnSync('/bin/sh', ['-c', `"$0" --a p --b s --c="$(printf '%b' '${esc}')"`, EXE],
    { encoding: 'utf8' });
  const m = ((r.stderr || '').trim().split('\n').pop() || '').match(/invalid int value: (.*)$/);
  return m ? m[1] : null;
}

const alphabet = [...'\'"\\\n\r\t\v\f\x1b abzX09_+-.', '­', '​', '́',
  '\u{1f600}', '\udcff', '\udc80', '\udcad', ' ', ' ', '\u{1d7d9}', '٠', '�', '\u{e0001}'];

let n = 0, fail = 0;
// Targeted cases first: leading dash and lone surrogates, the two suspects.
const targeted = ['-x', "-'a", '-\udcff', '\udcff9', 'b\udcff\t\r_', '\udcad', '\udc80z',
  "a'\"b", '\\\udcff\'"', '-\udcadz', '--', '-.'];
for (const s of [...targeted]) {
  const ref = refRepr(s);
  if (ref === null) continue;
  n++;
  if (pyRepr(s) !== ref) { fail++; console.log('FAIL targeted', JSON.stringify(s), '\n  mine', pyRepr(s), '\n  ref ', ref); }
}
for (let i = 0; i < 500; i++) {
  const len = 1 + Math.floor(Math.random() * 7);
  let s = '';
  for (let j = 0; j < len; j++) s += alphabet[Math.floor(Math.random() * alphabet.length)];
  const ref = refRepr(s);
  if (ref === null) continue;
  n++;
  if (pyRepr(s) !== ref) {
    fail++;
    if (fail <= 12) console.log('FAIL', JSON.stringify(s), '\n  mine', pyRepr(s), '\n  ref ', ref);
  }
}
console.log(`byte-accurate repr fuzz: ${n} strings -> ${fail === 0 ? 'ALL PASS' : fail + ' FAILURES'}`);

